        [Fact]
        public void ThermalTransmitance_QuantityInfo_ReturnsQuantityInfoDescribingQuantity()
        {
            ThermalTransmitanceUnit[] unitsOrderedByName = EnumHelper.GetValues<ThermalTransmitanceUnit>().OrderBy(x => x.ToString(), StringComparer.OrdinalIgnoreCase).ToArray();
            var quantity = new ThermalTransmitance(1, ThermalTransmitanceUnit.KilowattPerSquareMeterKelvin);

            QuantityInfo<ThermalTransmitance, ThermalTransmitanceUnit> quantityInfo = quantity.QuantityInfo;

            Assert.Equal("ThermalTransmitance", quantityInfo.Name);
            Assert.Equal(ThermalTransmitance.Zero, quantityInfo.Zero);
            Assert.Equal(ThermalTransmitance.BaseUnit, quantityInfo.BaseUnitInfo.Value);
            Assert.Equal(unitsOrderedByName, quantityInfo.Units);
            Assert.Equal(unitsOrderedByName, quantityInfo.UnitInfos.Select(x => x.Value));
            Assert.Equal(ThermalTransmitance.Info, quantityInfo);
            Assert.Equal(quantityInfo, ((IQuantity)quantity).QuantityInfo);
            Assert.Equal(quantityInfo, ((IQuantity<ThermalTransmitanceUnit>)quantity).QuantityInfo);
        }

        [Fact]
        public void ThermalTransmitanceInfo_CreateWithCustomUnitInfos()
        {
            ThermalTransmitanceUnit[] expectedUnits = [ThermalTransmitanceUnit.KilowattPerSquareMeterKelvin];

            ThermalTransmitance.ThermalTransmitanceInfo quantityInfo = ThermalTransmitance.ThermalTransmitanceInfo.CreateDefault(mappings => mappings.SelectUnits(expectedUnits));

            Assert.Equal("ThermalTransmitance", quantityInfo.Name);
