        [Fact]
        public void ConversionRoundTrip()
        {
            ThermalTransmitance kilowattpersquaremeterkelvin = ThermalTransmitance.FromKilowattsPerSquareMeterKelvin(3);
            Assert.Equal(3, ThermalTransmitance.FromBtusPerHourSquareFeetDegreeFahrenheit(kilowattpersquaremeterkelvin.BtusPerHourSquareFeetDegreeFahrenheit).KilowattsPerSquareMeterKelvin);
            Assert.Equal(3, ThermalTransmitance.FromKilocaloriesPerSquareCentimeterHourDegreeCelsius(kilowattpersquaremeterkelvin.KilocaloriesPerSquareCentimeterHourDegreeCelsius).KilowattsPerSquareMeterKelvin);
            Assert.Equal(3, ThermalTransmitance.FromKilowattsPerSquareMeterKelvin(kilowattpersquaremeterkelvin.KilowattsPerSquareMeterKelvin).KilowattsPerSquareMeterKelvin);
            Assert.Equal(3, ThermalTransmitance.FromWattsPerSquareCentimeterKelvin(kilowattpersquaremeterkelvin.WattsPerSquareCentimeterKelvin).KilowattsPerSquareMeterKelvin);
            Assert.Equal(3, ThermalTransmitance.FromWattsPerSquareMeterDegreeCelsius(kilowattpersquaremeterkelvin.WattsPerSquareMeterDegreeCelsius).KilowattsPerSquareMeterKelvin);
            Assert.Equal(3, ThermalTransmitance.FromWattsPerSquareMeterKelvin(kilowattpersquaremeterkelvin.WattsPerSquareMeterKelvin).KilowattsPerSquareMeterKelvin);
            Assert.Equal(3, ThermalTransmitance.FromWattsPerSquareMillimeterKelvin(kilowattpersquaremeterkelvin.WattsPerSquareMillimeterKelvin).KilowattsPerSquareMeterKelvin);
        }

        [Fact]
        public void ArithmeticOperators()
        {
            ThermalTransmitance v = ThermalTransmitance.FromKilowattsPerSquareMeterKelvin(1);
            Assert.Equal(-1, -v.KilowattsPerSquareMeterKelvin);
            Assert.Equal(2, (ThermalTransmitance.FromKilowattsPerSquareMeterKelvin(3) - v).KilowattsPerSquareMeterKelvin);
            Assert.Equal(2, (v + v).KilowattsPerSquareMeterKelvin);
            Assert.Equal(10, (v * 10).KilowattsPerSquareMeterKelvin);
            Assert.Equal(10, (10 * v).KilowattsPerSquareMeterKelvin);
            Assert.Equal(2, (ThermalTransmitance.FromKilowattsPerSquareMeterKelvin(10) / 5).KilowattsPerSquareMeterKelvin);
            Assert.Equal(2, ThermalTransmitance.FromKilowattsPerSquareMeterKelvin(10) / ThermalTransmitance.FromKilowattsPerSquareMeterKelvin(5));
        }

        [Fact]
        public void ComparisonOperators()
        {
            ThermalTransmitance oneKilowattPerSquareMeterKelvin = ThermalTransmitance.FromKilowattsPerSquareMeterKelvin(1);
            ThermalTransmitance twoKilowattsPerSquareMeterKelvin = ThermalTransmitance.FromKilowattsPerSquareMeterKelvin(2);

            Assert.True(oneKilowattPerSquareMeterKelvin < twoKilowattsPerSquareMeterKelvin);
            Assert.True(oneKilowattPerSquareMeterKelvin <= twoKilowattsPerSquareMeterKelvin);
            Assert.True(twoKilowattsPerSquareMeterKelvin > oneKilowattPerSquareMeterKelvin);
            Assert.True(twoKilowattsPerSquareMeterKelvin >= oneKilowattPerSquareMeterKelvin);

            Assert.False(oneKilowattPerSquareMeterKelvin > twoKilowattsPerSquareMeterKelvin);
            Assert.False(oneKilowattPerSquareMeterKelvin >= twoKilowattsPerSquareMeterKelvin);
            Assert.False(twoKilowattsPerSquareMeterKelvin < oneKilowattPerSquareMeterKelvin);
            Assert.False(twoKilowattsPerSquareMeterKelvin <= oneKilowattPerSquareMeterKelvin);
        }

