        [Theory]
        [InlineData(1, ThermalTransmitanceUnit.KilowattPerSquareMeterKelvin, 1, ThermalTransmitanceUnit.KilowattPerSquareMeterKelvin, true)]  // Same value and unit.
        [InlineData(1, ThermalTransmitanceUnit.KilowattPerSquareMeterKelvin, 2, ThermalTransmitanceUnit.KilowattPerSquareMeterKelvin, false)] // Different value.
        public void Equals_ReturnsTrue_IfValueAndUnitAreEqual(double valueA, ThermalTransmitanceUnit unitA, double valueB, ThermalTransmitanceUnit unitB, bool expectEqual)
        {
            var a = new ThermalTransmitance(valueA, unitA);
            var b = new ThermalTransmitance(valueB, unitB);

            // Operator overloads.
            Assert.Equal(expectEqual, a == b);
            Assert.Equal(expectEqual, b == a);
            Assert.Equal(!expectEqual, a != b);
            Assert.Equal(!expectEqual, b != a);

            // IEquatable<T>
            Assert.Equal(expectEqual, a.Equals(b));
            Assert.Equal(expectEqual, b.Equals(a));

            // IEquatable
            Assert.Equal(expectEqual, a.Equals((object)b));
            Assert.Equal(expectEqual, b.Equals((object)a));
        }

        [Fact]
        public void Equals_Null_ReturnsFalse()
        {
            var a = ThermalTransmitance.Zero;

            Assert.False(a.Equals((object)null));

            // "The result of the expression is always 'false'..."
            #pragma warning disable CS8073
            Assert.False(a == null);
            Assert.False(null == a);
            Assert.True(a != null);
            Assert.True(null != a);
            #pragma warning restore CS8073
        }

