        [Fact]
        public void ToString_WithSwedishCulture_ReturnsUnitAbbreviationForEnglishCultureSinceThereAreNoMappings()
        {
            // Chose this culture, because we don't currently have any abbreviations mapped for that culture and we expect the en-US to be used as fallback.
            var swedishCulture = CultureInfo.GetCultureInfo("sv-SE");

            Assert.Equal("1 Btu/Hrft²°F", new ThermalTransmitance(1, ThermalTransmitanceUnit.BtuPerHourSquareFeetDegreeFahrenheit).ToString(swedishCulture));
            Assert.Equal("1 kcal/cm²Hr°C", new ThermalTransmitance(1, ThermalTransmitanceUnit.KilocaloriePerSquareCentimeterHourDegreeCelsius).ToString(swedishCulture));
            Assert.Equal("1 kW/m²K", new ThermalTransmitance(1, ThermalTransmitanceUnit.KilowattPerSquareMeterKelvin).ToString(swedishCulture));
            Assert.Equal("1 W/cm²K", new ThermalTransmitance(1, ThermalTransmitanceUnit.WattPerSquareCentimeterKelvin).ToString(swedishCulture));
            Assert.Equal("1 W/m²°C", new ThermalTransmitance(1, ThermalTransmitanceUnit.WattPerSquareMeterDegreeCelsius).ToString(swedishCulture));
            Assert.Equal("1 W/m²K", new ThermalTransmitance(1, ThermalTransmitanceUnit.WattPerSquareMeterKelvin).ToString(swedishCulture));
            Assert.Equal("1 W/mm²K", new ThermalTransmitance(1, ThermalTransmitanceUnit.WattPerSquareMillimeterKelvin).ToString(swedishCulture));
        }

